configuration.tbelScript:
function containsVal(arr, v) {
  for (x : arr) {
    if (('' + x) == ('' + v)) { return true; }
  }
  return false;
}
function addUnique(arr, v) {
  if (!containsVal(arr, v)) { arr.add(v); }
}
function splitCsv(s) {
  var out = [];
  if (s == null) { return out; }
  var parts = ('' + s).split(',');
  for (p : parts) {
    var t = ('' + p).trim();
    if (t != '') { out.add(t); }
  }
  return out;
}
function diff(a, b) {
  var out = [];
  for (x : a) {
    if (!containsVal(b, x)) { out.add(x); }
  }
  return out;
}
function joinCsv(arr) {
  var s = '';
  for (i = 0; i < arr.size(); i++) {
    if (i > 0) { s = s + ', '; }
    s = s + ('' + arr.get(i));
  }
  return s;
}
function addMapCount(m, k, field) {
  var cur = m[k];
  if (cur == null) {
    cur = {'only_in_device': 0, 'only_in_tb': 0, 'total': 0};
  }
  cur[field] = cur[field] + 1;
  cur['total'] = cur['only_in_device'] + cur['only_in_tb'];
  m[k] = cur;
}

// NIC snapshot (aa) is authoritative current-active view.
var nicActive = [];
var mappedActive = msg['mappedActiveAlarms'];
if (mappedActive != null) {
  for (a : mappedActive) {
    if (a != null && a['canonicalAlarm'] != null) {
      addUnique(nicActive, a['canonicalAlarm']);
    }
  }
}

var tbActive = [];
var tbRaw = msg['tb.active_alarm_types'];
if (tbRaw == null) { tbRaw = metadata['tb.active_alarm_types']; }
if (tbRaw != null) {
  var parsedAsCollection = false;
  if (tbRaw.size != null && tbRaw.get != null) {
    parsedAsCollection = true;
    for (x : tbRaw) { if (x != null) { addUnique(tbActive, '' + x); } }
  }
  if (!parsedAsCollection) {
    var tbStr = '' + tbRaw;
    if (tbStr.startsWith('[')) {
      var parsed = JSON.parse(tbStr);
      if (parsed != null) {
        for (x : parsed) { if (x != null) { addUnique(tbActive, '' + x); } }
      }
    } else {
      var csv = splitCsv(tbStr);
      for (x : csv) { addUnique(tbActive, x); }
    }
  }
}

var onlyInDevice = diff(nicActive, tbActive);
var onlyInTb = diff(tbActive, nicActive);
var onlyInDeviceCount = onlyInDevice.size();
var onlyInTbCount = onlyInTb.size();
var mismatchTotal = onlyInDeviceCount + onlyInTbCount;
var inSync = (mismatchTotal == 0);

var mismatchSummary = 'IN_SYNC';
if (!inSync) {
  mismatchSummary = 'ONLY_DEVICE=' + onlyInDeviceCount + ', ONLY_TB=' + onlyInTbCount;
}

var mismatchAlarms = [];
for (x : onlyInDevice) { addUnique(mismatchAlarms, x); }
for (x : onlyInTb) { addUnique(mismatchAlarms, x); }

var mismatchByAlarm = {};
for (x : onlyInDevice) { addMapCount(mismatchByAlarm, '' + x, 'only_in_device'); }
for (x : onlyInTb) { addMapCount(mismatchByAlarm, '' + x, 'only_in_tb'); }

var nowTs = msg['ts'];
if (nowTs == null) { nowTs = metadata['ts']; }

var out = {
  'alarm.sync.nic_active': JSON.stringify(nicActive),
  'alarm.sync.tb_active': JSON.stringify(tbActive),
  'alarm.sync.only_in_device': JSON.stringify(onlyInDevice),
  'alarm.sync.only_in_tb': JSON.stringify(onlyInTb),
  'alarm.sync.only_in_device_csv': joinCsv(onlyInDevice),
  'alarm.sync.only_in_tb_csv': joinCsv(onlyInTb),
  'alarm.sync.only_in_device_count': onlyInDeviceCount,
  'alarm.sync.only_in_tb_count': onlyInTbCount,
  'alarm.sync.mismatch_total': mismatchTotal,
  'alarm.sync.mismatch_summary': mismatchSummary,
  'alarm.sync.mismatch_alarms_csv': joinCsv(mismatchAlarms),
  'alarm.sync.mismatch_by_alarm': JSON.stringify(mismatchByAlarm),
  'alarm.sync.in_sync': inSync,
  'alarm.sync.last_ts': nowTs
};

return {msg: out, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST'};
